from typing import Literal

from pydantic import BaseModel, Field

Likelihood = Literal["unlikely", "possible", "likely"]
GrowthStage = Literal[
    "germination", "seedling", "vegetative", "flowering", "fruiting", "maturity"
]


class ErrorResponse(BaseModel):
    detail: str


class ResponseMeta(BaseModel):
    """Server-added metadata. Never generated by the LLM."""

    model: str = Field(description="Gemini model that produced the assessment")
    method: Literal["llm_advisory"] = "llm_advisory"
    disclaimer: str = (
        "LLM-generated advisory from a photo, not a validated diagnosis. "
        "Confirm with field inspection or laboratory testing."
    )
